import {percentageChange} from './percentage-math.js';
// Retain experiment settings when guided steps or language changes redraw the lesson.
const experiment={mode:'increase',base:400,percent:25,secondPercent:25,firstDirection:'increase',secondDirection:'decrease'};
const format=n=>Number(n.toFixed(4)).toLocaleString('en-IN',{maximumFractionDigits:4});
export function percentageLessonMarkup(bi){return `<section class="change-lab" aria-label="${bi('Percentage experiment','प्रतिशत प्रयोग')}"><div class="change-title"><span class="eyebrow">${bi('CHANGE IT. SEE IT. UNDERSTAND IT.','बदलें। देखें। समझें।')}</span><h3>${bi('What happens when a value changes?','मान बदलने पर क्या होता है?')}</h3></div><div class="change-tabs" role="group" aria-label="${bi('Percentage lesson mode','प्रतिशत पाठ का प्रकार')}">${[['meaning',bi('Meaning','अर्थ')],['increase',bi('Increase','वृद्धि')],['decrease',bi('Decrease','कमी')],['successive',bi('Two changes','दो बदलाव')]].map(([id,label])=>`<button data-change-mode="${id}" aria-pressed="${experiment.mode===id}" class="${experiment.mode===id?'active':''}">${label}</button>`).join('')}</div><div class="change-controls"><div>${slider('change-base',bi('Starting value','शुरुआती मान'),100,1000,experiment.base,'',10)}</div><div>${slider('change-percent',bi('First percentage','पहला प्रतिशत'),0,100,experiment.percent,'%')}</div></div><div id="second-controls" ${experiment.mode==='successive'?'':'hidden'}><div class="change-direction-grid"><label>${bi('First change','पहला बदलाव')}<select id="first-direction">${directionOptions(experiment.firstDirection,bi)}</select></label><label>${bi('Second change','दूसरा बदलाव')}<select id="second-direction">${directionOptions(experiment.secondDirection,bi)}</select></label></div>${slider('second-percent',bi('Second percentage','दूसरा प्रतिशत'),0,100,experiment.secondPercent,'%')}</div><div id="change-visual"></div><div id="change-teaching" class="change-teaching" aria-live="polite" aria-atomic="true"></div><div class="change-try"><strong>${bi('Try it yourself','खुद आजमाएं')}</strong><p id="change-prompt"></p><button id="change-example" class="secondary">${bi('Try 20% up, then 20% down','20% वृद्धि, फिर 20% कमी आजमाएं')}</button></div></section>`;}
function directionOptions(value,bi){return `<option value="increase" ${value==='increase'?'selected':''}>${bi('Increase (+)','वृद्धि (+)')}</option><option value="decrease" ${value==='decrease'?'selected':''}>${bi('Decrease (−)','कमी (−)')}</option>`;}
function slider(id,label,min,max,value,suffix='',step=1){return `<label class="range-label" for="${id}"><span>${label}</span><output id="${id}-out" for="${id}">${value}${suffix}</output></label><input id="${id}" type="range" min="${min}" max="${max}" value="${value}" step="${step}">`;}
export function bindPercentageLesson(bi){
 const $=s=>document.querySelector(s),e=experiment;
 function render(){
   const priorWidths=[...document.querySelectorAll('.change-track>i:not(.removed)')].map(bar=>bar.style.width);
   const two=e.mode==='successive',meaning=e.mode==='meaning',dir=two?e.firstDirection:e.mode==='decrease'?'decrease':'increase';
   const c=percentageChange(e.base,e.percent,dir,two?e.secondPercent:null,e.secondDirection),amount=e.base*e.percent/100;
   document.querySelectorAll('[data-change-mode]').forEach(b=>{const chosen=b.dataset.changeMode===e.mode;b.classList.toggle('active',chosen);b.setAttribute('aria-pressed',String(chosen));});
   $('#second-controls').hidden=!two;
   for(const [id,value,suffix] of [['change-base',e.base,''],['change-percent',e.percent,'%'],['second-percent',e.secondPercent,'%']]){$('#'+id).value=value;$('#'+id+'-out').textContent=format(value)+suffix;}
   $('#first-direction').value=e.firstDirection;$('#second-direction').value=e.secondDirection;
   const limit=Math.max(e.base,c.afterFirst,c.final),up=dir==='increase',up2=e.secondDirection==='increase';
   const bar=(label,value,color,delta='',prior=null)=>`<div class="change-bar-row"><div><span>${label}</span><strong>${format(value)}</strong></div><div class="change-track"><i class="${color}" style="width:${value/limit*100}%"></i>${prior!==null&&prior>value?`<i class="removed" style="left:${value/limit*100}%;width:${(prior-value)/limit*100}%"></i>`:''}</div>${delta?`<small>${delta}</small>`:''}</div>`;
   if(meaning){$('#change-visual').innerHTML=`<div class="change-meaning"><div class="change-hundred" aria-hidden="true">${Array.from({length:100},(_,i)=>`<i class="${i<e.percent?'on':''}"></i>`).join('')}</div><div><span>${bi('THE PART','भाग')}</span><strong>${format(amount)}</strong><p>${e.percent}% ${bi('of','का')} ${format(e.base)}</p></div></div>`;
     $('#change-teaching').innerHTML=`<strong>${bi('A percentage means “out of 100”.','प्रतिशत का अर्थ है “100 में से”।')}</strong><p>${bi(`Each square is 1% of ${format(e.base)} = ${format(e.base/100)}. The ${e.percent} coloured squares represent ${format(amount)}.`,`हर वर्ग ${format(e.base)} का 1% = ${format(e.base/100)} है। ${e.percent} रंगीन वर्ग ${format(amount)} दर्शाते हैं।`)}</p><div class="change-equation">${format(e.base)} × ${e.percent} ÷ 100 = <b>${format(amount)}</b></div>`;
   }else{$('#change-visual').innerHTML=`<div class="change-chart" aria-label="${bi('Before and after values on the same scale','एक ही पैमाने पर पहले और बाद के मान')}">${bar(bi('Starting value','शुरुआती मान'),e.base,'baseline')}${bar(two?bi('After first change','पहले बदलाव के बाद'):bi('New value','नया मान'),c.afterFirst,up?'addition':'reduction',`${up?'+':'−'}${format(c.firstChange)} · ${e.percent}% ${up?bi('increase','वृद्धि'):bi('decrease','कमी')}`,e.base)}${two?bar(bi('Final value','अंतिम मान'),c.final,up2?'addition':'reduction',`${up2?'+':'−'}${format(c.secondChange)} · ${e.secondPercent}% ${up2?bi('increase','वृद्धि'):bi('decrease','कमी')}`,c.afterFirst):''}<p class="scale-note">${bi('All bars use the same scale. Hatched space shows the amount removed.','सभी पट्टियां एक ही पैमाने पर हैं। धारीदार भाग घटाई गई मात्रा दिखाता है।')}</p></div><div class="change-net ${c.net<0?'loss':'gain'}"><span>${bi('OVERALL CHANGE','कुल बदलाव')}</span><strong>${c.net>0?'+':c.net<0?'−':''}${format(Math.abs(c.net))} <small>(${c.netPercent>0?'+':c.netPercent<0?'−':''}${format(Math.abs(c.netPercent))}%)</small></strong></div>`;
    if(!matchMedia('(prefers-reduced-motion: reduce)').matches)document.querySelectorAll('.change-track>i:not(.removed)').forEach((bar,i)=>bar.animate([{width:priorWidths[i]||'0%'},{width:bar.style.width}],{duration:240,easing:'ease-out'}));
    const step1=`${format(e.base)} × ${e.percent} ÷ 100 = ${format(c.firstChange)}`;
    const step2=`${format(e.base)} ${up?'+':'−'} ${format(c.firstChange)} = ${format(c.afterFirst)}`;
    $('#change-teaching').innerHTML=`<strong>${bi('Follow the change','बदलाव को समझें')}</strong><ol><li>${bi('Find the change using the starting value.','शुरुआती मान से बदलाव की मात्रा निकालें।')}<b>${step1}</b></li><li>${up?bi('Add it to the starting value.','इसे शुरुआती मान में जोड़ें।'):bi('Remove it from the starting value.','इसे शुरुआती मान से घटाएं।')}<b>${step2}</b></li>${two?`<li>${bi(`The second change uses ${format(c.afterFirst)} as its base, not ${format(e.base)}.`,`दूसरे बदलाव का आधार ${format(c.afterFirst)} है, ${format(e.base)} नहीं।`)}<b>${format(c.afterFirst)} × ${e.secondPercent} ÷ 100 = ${format(c.secondChange)}</b><b>${format(c.afterFirst)} ${up2?'+':'−'} ${format(c.secondChange)} = ${format(c.final)}</b></li>`:''}</ol>${two?`<p class="change-insight">${bi('The base changes after each step. Equal percentages in opposite directions do not generally cancel.','हर चरण के बाद आधार बदलता है। विपरीत दिशाओं में बराबर प्रतिशत आम तौर पर एक-दूसरे को रद्द नहीं करते।')}</p>`:''}`;
   }
   $('#change-prompt').textContent=meaning?bi('Keep the percentage fixed and change the starting value. Why does the part change?','प्रतिशत स्थिर रखें और शुरुआती मान बदलें। भाग क्यों बदलता है?'):two?bi('Set both percentages to 20. Predict the final value before looking at the last bar.','दोनों प्रतिशत 20 रखें। अंतिम पट्टी देखने से पहले अंतिम मान का अनुमान लगाएं।'):bi('Move the percentage to 0%, 50% and 100%. Watch how much is added or removed.','प्रतिशत को 0%, 50% और 100% करें। देखें कितनी मात्रा जुड़ती या घटती है।');
 }
 document.querySelectorAll('[data-change-mode]').forEach(b=>b.onclick=()=>{e.mode=b.dataset.changeMode;render();});
 for(const [id,key] of [['change-base','base'],['change-percent','percent'],['second-percent','secondPercent']])$('#'+id).oninput=event=>{e[key]=Number(event.target.value);render();};
 $('#first-direction').onchange=event=>{e.firstDirection=event.target.value;render();};$('#second-direction').onchange=event=>{e.secondDirection=event.target.value;render();};
 $('#change-example').onclick=()=>{Object.assign(e,{mode:'successive',base:500,percent:20,secondPercent:20,firstDirection:'increase',secondDirection:'decrease'});render();};
 render();
}
